import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { MessageCircle, CheckCircle } from 'lucide-react';
import api from '../services/api';

export default function Mensagens() {
  const { user } = useAuth();
  const [notifs, setNotifs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [turmas, setTurmas] = useState([]);
  const [form, setForm] = useState({ titulo: '', mensagem: '', alvo: user?.role === 'admin' ? 'todos' : 'alunos', turma_id: '' });
  const [erro, setErro] = useState('');
  const [ok, setOk] = useState('');
  const bottomRef = useRef(null);

  useEffect(() => {
    api.get('/notificacoes').then(res => setNotifs(res.data)).catch(() => {}).finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    if (!user) return;
    if (user.role === 'admin' || user.role === 'coordenador') {
      api.get('/staff/turmas').then(res => setTurmas(res.data)).catch(() => {});
    } else if (user.role === 'professor') {
      api.get('/professor/minhas-disciplinas')
        .then(res => {
          const mapa = new Map();
          res.data.forEach((d) => {
            if (!mapa.has(d.turma_id)) mapa.set(d.turma_id, { turma_id: d.turma_id, nome: d.turma_nome });
          });
          setTurmas(Array.from(mapa.values()));
        })
        .catch(() => {});
    }
  }, [user]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [notifs]);

  const marcarLida = (id) => {
    setNotifs(prev => prev.map(n => n.id === id ? { ...n, lida: true } : n));
    api.patch(`/notificacoes/${id}/lida`).catch(() => {});
  };

  const enviarMensagem = async (e) => {
    e.preventDefault();
    setErro('');
    setOk('');
    if (!form.titulo || !form.mensagem) {
      return setErro('Título e mensagem são obrigatórios.');
    }
    if (user && ['professor', 'coordenador'].includes(user.role) && !form.turma_id) {
      return setErro('Seleccione a turma para enviar a mensagem.');
    }
    try {
      await api.post('/notificacoes', form);
      setOk('Mensagem enviada. Os destinatários receberão a notificação no portal.');
      setForm({ ...form, titulo: '', mensagem: '' });
      const res = await api.get('/notificacoes');
      setNotifs(res.data);
    } catch (err) {
      setErro(err.response?.data?.message || 'Erro ao enviar mensagem.');
    }
  };

  if (loading) return <div className="loading"><div className="spinner" /></div>;

  const naoLidas = notifs.filter(n => !n.lida).length;

  return (
    <div className="page-container">
      <div className="page-header">
<div
  style={{
    display: 'flex',
    alignItems: 'center',
    gap: '10px'
  }}
>
  <h2>Mensagens e Notificações</h2>

  {naoLidas > 0 && (
    <span
      style={{
        background: '#dc2626',
        color: '#fff',
        borderRadius: '50%',
        width: '28px',
        height: '28px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontSize: '13px',
        fontWeight: 'bold'
      }}
    >
      {naoLidas}
    </span>
  )}
</div>
      </div>

      {(user?.role === 'admin' || user?.role === 'coordenador' || user?.role === 'professor') && (
        <div className="card" style={{ marginBottom: '1.5rem' }}>
          <h3 style={{ marginTop: 0, marginBottom: '1rem' }}>Enviar mensagem</h3>
          {(erro || ok) && (
            <div className={`alert ${erro ? 'alert-error' : 'alert-success'}`} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <span>{erro || ok}</span>
              <button type="button" className="alert-close" onClick={() => { if (erro) setErro(''); else setOk(''); }}>×</button>
            </div>
          )}
          <form onSubmit={enviarMensagem}>
            <div className="form-row">
              <div className="form-group">
                <label className="form-label">Título</label>
                <input className="form-control" value={form.titulo} onChange={e => setForm({ ...form, titulo: e.target.value })} />
              </div>
              <div className="form-group">
                <label className="form-label">Destinatário</label>
                <select className="form-control form-select" value={form.alvo} onChange={e => setForm({ ...form, alvo: e.target.value })}>
                  {user.role === 'admin' ? (
                    <>
                      <option value="todos">Todos</option>
                      <option value="alunos">Alunos</option>
                      <option value="professores">Professores</option>
                      <option value="coordenadores">Coordenadores</option>
                    </>
                  ) : user.role === 'coordenador' ? (
                    <>
                      <option value="alunos">Alunos</option>
                      <option value="professores">Professores</option>
                    </>
                  ) : (
                    <option value="alunos">Alunos</option>
                  )}
                </select>
              </div>
            </div>
            {(user.role === 'coordenador' || user.role === 'professor') && (
              <div className="form-group">
                <label className="form-label">Turma</label>
                <select className="form-control form-select" value={form.turma_id} onChange={e => setForm({ ...form, turma_id: e.target.value })}>
                  <option value="">Seleccione a turma...</option>
                  {turmas.map(t => (
                    <option key={t.id || t.turma_id} value={t.id || t.turma_id}>{t.nome || t.turma_nome}</option>
                  ))}
                </select>
              </div>
            )}
            <div className="form-group">
              <label className="form-label">Mensagem</label>
              <textarea className="form-control" rows="3" value={form.mensagem} onChange={e => setForm({ ...form, mensagem: e.target.value })} />
            </div>
            <button type="submit" className="btn btn-primary">Enviar</button>
          </form>
        </div>
      )}

      <div className="card">
        {notifs.length === 0 ? (
          <div className="empty-state">
            <MessageCircle size={48} />
            <h3>Nenhuma mensagem ainda</h3>
            <p>As notificações da escola aparecerão aqui.</p>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            {notifs.map(n => (
              <div
                key={n.id}
                onClick={() => !n.lida && marcarLida(n.id)}
                style={{
                  display: 'flex', gap: 16, alignItems: 'flex-start',
                  padding: '1rem 1.25rem', borderRadius: 12,
                  background: n.lida ? 'var(--bege-claro)' : 'var(--laranja-suave)',
                  border: n.lida ? '1px solid var(--bege)' : '1px solid rgba(232,100,26,0.25)',
                  cursor: n.lida ? 'default' : 'pointer', transition: 'all 0.2s'
                }}
              >
                <div style={{ width: 42, height: 42, borderRadius: '50%', flexShrink: 0, background: n.lida ? 'var(--bege)' : 'var(--laranja)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <MessageCircle size={18} color={n.lida ? 'var(--cinza)' : 'white'} />
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 8, flexWrap: 'wrap' }}>
                    <div style={{ minWidth: 0 }}>
                      <p style={{ fontSize: '0.95rem', fontWeight: 700, margin: 0, color: 'var(--castanho-escuro)' }}>{n.titulo}</p>
                      <p style={{ fontSize: '0.9rem', fontWeight: n.lida ? 400 : 500, color: 'var(--castanho)', margin: '0.35rem 0 0 0' }}>{n.mensagem}</p>
                    </div>
                    {!n.lida && <span style={{ width: 8, height: 8, borderRadius: '50%', background: 'var(--laranja)', flexShrink: 0, marginTop: 4 }} />}
                  </div>
                  <div style={{ display: 'flex', gap: 12, marginTop: 6, alignItems: 'center', flexWrap: 'wrap' }}>
                    {n.criado_em && <span style={{ fontSize: '0.75rem', color: 'var(--cinza)' }}>{new Date(n.criado_em).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short', year: 'numeric' })}</span>}
                    <span style={{ fontSize: '0.72rem', fontWeight: 600, textTransform: 'uppercase', color: n.lida ? 'var(--cinza)' : 'var(--laranja)' }}>{n.lida ? 'Lida' : 'Nova'}</span>
                    {!n.lida && <span style={{ fontSize: '0.75rem', color: 'var(--laranja)', fontWeight: 600 }}>Clica para marcar como lida</span>}
                  </div>
                </div>
              </div>
            ))}
            <div ref={bottomRef} />
          </div>
        )}
      </div>
    </div>
  );
}
